-- WASSCE Biology 2023 Questions (50 questions)
-- Adding 2023 past paper to complete the set

INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, total_questions, total_marks, time_allowed, is_complete)
VALUES ('pp_wassce_bio_2023_1', 'exam_wassce', 'subj_wassce_biology', 'paper_wassce_1', 2023, 'May-June', 50, 50, 60, 1);

INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Cell Biology (1-10)
('q_bio_2023_001', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The powerhouse of the cell is the:', 'multiple_choice', '["A. Nucleus", "B. Ribosome", "C. Mitochondrion", "D. Golgi apparatus"]', 'C', 'Mitochondria are called the powerhouse of the cell because they produce ATP through cellular respiration.', 'easy', 1, 1),
('q_bio_2023_002', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Which organelle is responsible for protein synthesis?', 'multiple_choice', '["A. Lysosome", "B. Ribosome", "C. Vacuole", "D. Centriole"]', 'B', 'Ribosomes are the sites of protein synthesis, translating mRNA into polypeptide chains.', 'easy', 1, 2),
('q_bio_2023_003', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The cell membrane is described as selectively permeable because it:', 'multiple_choice', '["A. Allows all substances to pass through", "B. Prevents all substances from passing", "C. Allows only certain substances to pass", "D. Is completely impermeable"]', 'C', 'The cell membrane is selectively permeable, controlling which substances enter and exit the cell.', 'medium', 1, 3),
('q_bio_2023_004', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Which of the following is NOT found in plant cells?', 'multiple_choice', '["A. Cell wall", "B. Chloroplast", "C. Centriole", "D. Large central vacuole"]', 'C', 'Centrioles are typically found in animal cells and are involved in cell division. Plant cells usually lack centrioles.', 'medium', 1, 4),
('q_bio_2023_005', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Osmosis is the movement of:', 'multiple_choice', '["A. Solute from low to high concentration", "B. Water from high to low water potential", "C. Gases across a membrane", "D. Nutrients into cells"]', 'B', 'Osmosis is the movement of water molecules from a region of higher water potential to lower water potential through a semi-permeable membrane.', 'medium', 1, 5),
('q_bio_2023_006', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The Golgi apparatus is responsible for:', 'multiple_choice', '["A. Energy production", "B. Protein modification and packaging", "C. DNA replication", "D. Photosynthesis"]', 'B', 'The Golgi apparatus modifies, packages, and distributes proteins and lipids produced by the endoplasmic reticulum.', 'medium', 1, 6),
('q_bio_2023_007', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Lysosomes contain:', 'multiple_choice', '["A. Genetic material", "B. Digestive enzymes", "C. Chlorophyll", "D. Starch"]', 'B', 'Lysosomes are membrane-bound organelles containing digestive enzymes that break down waste materials and cellular debris.', 'easy', 1, 7),
('q_bio_2023_008', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Active transport differs from passive transport because it:', 'multiple_choice', '["A. Does not require energy", "B. Requires energy (ATP)", "C. Only occurs in plants", "D. Moves substances down a gradient"]', 'B', 'Active transport requires energy (ATP) to move substances against their concentration gradient.', 'medium', 1, 8),
('q_bio_2023_009', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The phase of mitosis where chromosomes align at the cell equator is:', 'multiple_choice', '["A. Prophase", "B. Metaphase", "C. Anaphase", "D. Telophase"]', 'B', 'During metaphase, chromosomes line up at the metaphase plate (cell equator) before being separated.', 'medium', 1, 9),
('q_bio_2023_010', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Meiosis produces:', 'multiple_choice', '["A. Two diploid cells", "B. Two haploid cells", "C. Four diploid cells", "D. Four haploid cells"]', 'D', 'Meiosis is a type of cell division that produces four haploid daughter cells, each with half the chromosome number.', 'easy', 1, 10),

-- Genetics and Heredity (11-20)
('q_bio_2023_011', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'A gene is a segment of:', 'multiple_choice', '["A. Protein", "B. Carbohydrate", "C. DNA", "D. Lipid"]', 'C', 'A gene is a segment of DNA that contains the instructions for making a specific protein or functional RNA.', 'easy', 1, 11),
('q_bio_2023_012', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'In a monohybrid cross between Tt and Tt, the phenotypic ratio is:', 'multiple_choice', '["A. 1:1", "B. 1:2:1", "C. 3:1", "D. 9:3:3:1"]', 'C', 'A monohybrid cross between two heterozygotes (Tt x Tt) produces a 3:1 phenotypic ratio (3 dominant: 1 recessive).', 'medium', 1, 12),
('q_bio_2023_013', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Which blood group is the universal donor?', 'multiple_choice', '["A. A", "B. B", "C. AB", "D. O"]', 'D', 'Blood group O is the universal donor because it lacks A and B antigens, so it can be given to any blood type.', 'easy', 1, 13),
('q_bio_2023_014', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Sickle cell anemia is an example of:', 'multiple_choice', '["A. Sex-linked inheritance", "B. Codominance", "C. Point mutation", "D. Polyploidy"]', 'C', 'Sickle cell anemia results from a point mutation in the hemoglobin gene, causing abnormal red blood cell shape.', 'medium', 1, 14),
('q_bio_2023_015', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The chromosome composition of a human male is:', 'multiple_choice', '["A. 44 + XX", "B. 44 + XY", "C. 22 + XY", "D. 46 + XY"]', 'B', 'Human males have 44 autosomes plus XY sex chromosomes, giving a total of 46 chromosomes.', 'easy', 1, 15),
('q_bio_2023_016', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Crossing over occurs during:', 'multiple_choice', '["A. Mitosis", "B. Prophase I of meiosis", "C. Metaphase II", "D. Interphase"]', 'B', 'Crossing over occurs during prophase I of meiosis when homologous chromosomes exchange genetic material.', 'medium', 1, 16),
('q_bio_2023_017', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'A person with genotype IAi has blood group:', 'multiple_choice', '["A. A", "B. B", "C. AB", "D. O"]', 'A', 'The IA allele is dominant over i, so IAi genotype results in blood group A.', 'medium', 1, 17),
('q_bio_2023_018', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Color blindness is more common in males because:', 'multiple_choice', '["A. Males have two X chromosomes", "B. The gene is on the Y chromosome", "C. The gene is recessive and X-linked", "D. Males are weaker"]', 'C', 'Color blindness is X-linked recessive, so males (XY) only need one copy of the defective gene to be affected.', 'hard', 1, 18),
('q_bio_2023_019', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The father of genetics is:', 'multiple_choice', '["A. Charles Darwin", "B. Gregor Mendel", "C. Louis Pasteur", "D. Robert Hooke"]', 'B', 'Gregor Mendel is known as the father of genetics for his work on inheritance patterns in pea plants.', 'easy', 1, 19),
('q_bio_2023_020', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Down syndrome is caused by:', 'multiple_choice', '["A. Deletion of chromosome 21", "B. Trisomy 21", "C. Monosomy 21", "D. Translocation of chromosome 18"]', 'B', 'Down syndrome is caused by trisomy 21, meaning there are three copies of chromosome 21 instead of two.', 'medium', 1, 20),

-- Ecology and Environment (21-30)
('q_bio_2023_021', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The study of the relationship between organisms and their environment is called:', 'multiple_choice', '["A. Taxonomy", "B. Ecology", "C. Morphology", "D. Physiology"]', 'B', 'Ecology is the scientific study of interactions between organisms and their environment.', 'easy', 1, 21),
('q_bio_2023_022', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'In a food chain, the organism that makes its own food is called:', 'multiple_choice', '["A. Consumer", "B. Decomposer", "C. Producer", "D. Predator"]', 'C', 'Producers (autotrophs) make their own food through photosynthesis and form the base of food chains.', 'easy', 1, 22),
('q_bio_2023_023', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The nitrogen cycle includes the process of:', 'multiple_choice', '["A. Photosynthesis", "B. Nitrogen fixation", "C. Transpiration", "D. Glycolysis"]', 'B', 'Nitrogen fixation is a key process in the nitrogen cycle where atmospheric nitrogen is converted to usable forms.', 'medium', 1, 23),
('q_bio_2023_024', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'A symbiotic relationship where one organism benefits and the other is harmed is:', 'multiple_choice', '["A. Mutualism", "B. Commensalism", "C. Parasitism", "D. Competition"]', 'C', 'In parasitism, the parasite benefits at the expense of the host, which is harmed.', 'easy', 1, 24),
('q_bio_2023_025', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The greenhouse effect is caused mainly by:', 'multiple_choice', '["A. Oxygen", "B. Nitrogen", "C. Carbon dioxide", "D. Hydrogen"]', 'C', 'Carbon dioxide and other greenhouse gases trap heat in the atmosphere, causing the greenhouse effect.', 'easy', 1, 25),
('q_bio_2023_026', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'An ecosystem consists of:', 'multiple_choice', '["A. Only living organisms", "B. Only non-living factors", "C. Both biotic and abiotic components", "D. Only plants"]', 'C', 'An ecosystem includes both biotic (living) and abiotic (non-living) components interacting together.', 'easy', 1, 26),
('q_bio_2023_027', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Eutrophication in water bodies is caused by:', 'multiple_choice', '["A. Excess oxygen", "B. Excess nutrients", "C. Lack of sunlight", "D. Cold temperatures"]', 'B', 'Eutrophication occurs when excess nutrients (especially nitrogen and phosphorus) cause algal blooms in water bodies.', 'medium', 1, 27),
('q_bio_2023_028', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The ozone layer protects living things from:', 'multiple_choice', '["A. Infrared radiation", "B. Ultraviolet radiation", "C. Radio waves", "D. Visible light"]', 'B', 'The ozone layer in the stratosphere absorbs harmful ultraviolet (UV) radiation from the sun.', 'easy', 1, 28),
('q_bio_2023_029', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Succession that begins on bare rock is called:', 'multiple_choice', '["A. Secondary succession", "B. Primary succession", "C. Climax community", "D. Pioneer community"]', 'B', 'Primary succession occurs on barren surfaces like bare rock where no soil exists, starting with pioneer species.', 'medium', 1, 29),
('q_bio_2023_030', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The pyramid of energy is always:', 'multiple_choice', '["A. Inverted", "B. Upright", "C. Spindle-shaped", "D. Variable"]', 'B', 'The pyramid of energy is always upright because energy decreases at each trophic level due to the 10% rule.', 'medium', 1, 30),

-- Human Physiology (31-40)
('q_bio_2023_031', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The enzyme that digests starch in the mouth is:', 'multiple_choice', '["A. Pepsin", "B. Lipase", "C. Amylase", "D. Trypsin"]', 'C', 'Salivary amylase (ptyalin) in the mouth begins the digestion of starch into maltose.', 'easy', 1, 31),
('q_bio_2023_032', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The functional unit of the kidney is the:', 'multiple_choice', '["A. Neuron", "B. Nephron", "C. Alveolus", "D. Villus"]', 'B', 'The nephron is the functional unit of the kidney responsible for filtering blood and producing urine.', 'easy', 1, 32),
('q_bio_2023_033', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Deoxygenated blood enters the heart through the:', 'multiple_choice', '["A. Pulmonary vein", "B. Aorta", "C. Vena cava", "D. Pulmonary artery"]', 'C', 'Deoxygenated blood from the body returns to the right atrium via the superior and inferior vena cava.', 'medium', 1, 33),
('q_bio_2023_034', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Gas exchange in humans occurs in the:', 'multiple_choice', '["A. Bronchi", "B. Trachea", "C. Alveoli", "D. Bronchioles"]', 'C', 'Gas exchange occurs in the alveoli, where oxygen diffuses into the blood and carbon dioxide diffuses out.', 'easy', 1, 34),
('q_bio_2023_035', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The hormone that regulates blood sugar level is:', 'multiple_choice', '["A. Thyroxine", "B. Adrenaline", "C. Insulin", "D. Testosterone"]', 'C', 'Insulin, produced by the pancreas, regulates blood glucose levels by facilitating glucose uptake into cells.', 'easy', 1, 35),
('q_bio_2023_036', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The part of the brain that controls balance and coordination is the:', 'multiple_choice', '["A. Cerebrum", "B. Cerebellum", "C. Medulla oblongata", "D. Hypothalamus"]', 'B', 'The cerebellum coordinates voluntary movements, balance, and posture.', 'medium', 1, 36),
('q_bio_2023_037', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Antibodies are produced by:', 'multiple_choice', '["A. Red blood cells", "B. Platelets", "C. White blood cells", "D. Plasma"]', 'C', 'White blood cells (specifically B lymphocytes) produce antibodies as part of the immune response.', 'easy', 1, 37),
('q_bio_2023_038', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The condition where the eye cannot focus on near objects is called:', 'multiple_choice', '["A. Myopia", "B. Hypermetropia", "C. Astigmatism", "D. Presbyopia"]', 'B', 'Hypermetropia (farsightedness) is a condition where close objects appear blurry because the image focuses behind the retina.', 'medium', 1, 38),
('q_bio_2023_039', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Urea is produced in the:', 'multiple_choice', '["A. Kidney", "B. Liver", "C. Lungs", "D. Skin"]', 'B', 'Urea is produced in the liver through the deamination of amino acids and is then excreted by the kidneys.', 'medium', 1, 39),
('q_bio_2023_040', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The reflex arc consists of:', 'multiple_choice', '["A. Receptor, sensory neuron, brain, motor neuron, effector", "B. Receptor, sensory neuron, relay neuron, motor neuron, effector", "C. Brain, spinal cord, muscles", "D. Eyes, brain, hands"]', 'B', 'A reflex arc includes receptor, sensory neuron, relay neuron (in spinal cord), motor neuron, and effector.', 'hard', 1, 40),

-- Plant Biology and Evolution (41-50)
('q_bio_2023_041', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Photosynthesis occurs mainly in the:', 'multiple_choice', '["A. Root", "B. Stem", "C. Leaf", "D. Flower"]', 'C', 'Photosynthesis mainly occurs in leaves because they contain chloroplasts and have a large surface area for light absorption.', 'easy', 1, 41),
('q_bio_2023_042', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The tissue responsible for water transport in plants is:', 'multiple_choice', '["A. Phloem", "B. Xylem", "C. Cambium", "D. Epidermis"]', 'B', 'Xylem tissue transports water and dissolved minerals from roots to leaves through transpiration pull.', 'easy', 1, 42),
('q_bio_2023_043', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Stomata are mainly found on the:', 'multiple_choice', '["A. Upper surface of leaves", "B. Lower surface of leaves", "C. Roots", "D. Flowers"]', 'B', 'Stomata are mainly found on the lower epidermis of leaves to reduce water loss while allowing gas exchange.', 'easy', 1, 43),
('q_bio_2023_044', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The hormone that promotes cell elongation in plants is:', 'multiple_choice', '["A. Ethylene", "B. Auxin", "C. Abscisic acid", "D. Cytokinin"]', 'B', 'Auxin promotes cell elongation, especially in shoots, and is involved in phototropism and gravitropism.', 'medium', 1, 44),
('q_bio_2023_045', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Pollination is the transfer of pollen from:', 'multiple_choice', '["A. Stigma to ovary", "B. Anther to stigma", "C. Ovary to ovule", "D. Style to stigma"]', 'B', 'Pollination is the transfer of pollen grains from the anther (male part) to the stigma (female part) of a flower.', 'easy', 1, 45),
('q_bio_2023_046', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Natural selection was proposed by:', 'multiple_choice', '["A. Gregor Mendel", "B. Charles Darwin", "C. Jean Lamarck", "D. Louis Pasteur"]', 'B', 'Charles Darwin proposed the theory of evolution by natural selection in his book "On the Origin of Species."', 'easy', 1, 46),
('q_bio_2023_047', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Homologous structures indicate:', 'multiple_choice', '["A. Convergent evolution", "B. Common ancestry", "C. No relationship", "D. Parallel evolution"]', 'B', 'Homologous structures have similar anatomy but different functions, indicating common evolutionary ancestry.', 'medium', 1, 47),
('q_bio_2023_048', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'The term "survival of the fittest" means:', 'multiple_choice', '["A. Only the strongest survive", "B. The best adapted organisms survive to reproduce", "C. Fighting for survival", "D. Living the longest"]', 'B', 'Survival of the fittest means organisms best adapted to their environment are more likely to survive and reproduce.', 'medium', 1, 48),
('q_bio_2023_049', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Transpiration is important because it:', 'multiple_choice', '["A. Produces food", "B. Creates transpiration pull for water movement", "C. Produces oxygen", "D. Fixes nitrogen"]', 'B', 'Transpiration creates a pulling force (transpiration pull) that draws water up through the xylem from roots to leaves.', 'medium', 1, 49),
('q_bio_2023_050', 'subj_wassce_biology', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_bio_2023_1', 'Fossils provide evidence for evolution because they:', 'multiple_choice', '["A. Are found in all rocks", "B. Show changes in organisms over time", "C. Are always complete", "D. Are found in water only"]', 'B', 'Fossils show how organisms have changed over geological time, providing evidence for evolutionary transitions.', 'easy', 1, 50);
